        tensor_tmp = torch::sub(base_feature, match_feature);
        tensor_tmp = torch::pow(tensor_tmp, 2);
        tensor_sum = torch::sum(tensor_tmp, 1);
        sort_ret = torch::topk(tensor_sum, 1);
